// User-provided recordings, decoded PCM loops with matching tick/tock phases.
export const CLOCK_SOUNDS={
  standard: {label:"Standard · 기본", wav:""},
  big: {label:"Big Clock", wav:""},
  quick1: {label:"Quick 1", wav:""},
  quick2: {label:"Quick 2", wav:""}
};
const caches=new WeakMap();
export function clockType(value){return Object.hasOwn(CLOCK_SOUNDS,value)?value:'standard'}
export function loadClockBuffer(ctx,type){
 type=clockType(type);
 let cache=caches.get(ctx);if(!cache){cache=new Map();caches.set(ctx,cache)}
 if(!cache.has(type)){
  const bytes=Uint8Array.from(atob(CLOCK_SOUNDS[type].wav),c=>c.charCodeAt(0));
  const promise=ctx.decodeAudioData(bytes.buffer).catch(error=>{cache.delete(type);throw error});cache.set(type,promise);
 }
 return cache.get(type);
}
export function createClockVoice(ctx,buffer,{duration=null,volume=.65}={}){
 const source=ctx.createBufferSource(),gain=ctx.createGain(),now=ctx.currentTime;
 source.buffer=buffer;source.loop=true;source.loopStart=0;source.loopEnd=buffer.duration;
 source.connect(gain);gain.connect(ctx.destination);
 gain.gain.setValueAtTime(0,now);gain.gain.linearRampToValueAtTime(volume,now+.01);
 source.onended=()=>{source.disconnect();gain.disconnect()};
 source.start(now);
 if(duration!==null)source.stop(now+duration);
 let stopped=false;
 return {stop(){if(stopped)return;stopped=true;gain.gain.cancelScheduledValues(ctx.currentTime);gain.gain.setTargetAtTime(0,ctx.currentTime,.005);source.stop(ctx.currentTime+.03)}};
}
